-- AnnA Flow v0.9: estrutura isolada por cliente. Migração aditiva, não altera flow_runtime.
CREATE TABLE IF NOT EXISTS flow_clients (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name varchar(160) NOT NULL,segment varchar(32) NOT NULL CHECK(segment IN ('educacao','saude','empresa','publico','outro')),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS flow_client_units (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,client_id bigint NOT NULL REFERENCES flow_clients(id),name varchar(120) NOT NULL,active boolean NOT NULL DEFAULT true,UNIQUE(client_id,name),UNIQUE(id,client_id));
CREATE TABLE IF NOT EXISTS flow_client_services (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,client_id bigint NOT NULL REFERENCES flow_clients(id),unit_id bigint NOT NULL,name varchar(100) NOT NULL,priority_enabled boolean NOT NULL DEFAULT true,active boolean NOT NULL DEFAULT true,FOREIGN KEY(unit_id,client_id) REFERENCES flow_client_units(id,client_id),UNIQUE(unit_id,name),UNIQUE(id,unit_id));
CREATE TABLE IF NOT EXISTS flow_client_destinations (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,client_id bigint NOT NULL REFERENCES flow_clients(id),unit_id bigint NOT NULL,name varchar(100) NOT NULL,destination_type varchar(24) NOT NULL DEFAULT 'guiche' CHECK(destination_type IN ('guiche','sala','consultorio','setor','outro')),active boolean NOT NULL DEFAULT true,FOREIGN KEY(unit_id,client_id) REFERENCES flow_client_units(id,client_id),UNIQUE(unit_id,name));
CREATE TABLE IF NOT EXISTS flow_signage_profiles (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,client_id bigint NOT NULL REFERENCES flow_clients(id),unit_id bigint NOT NULL,name varchar(100) NOT NULL,theme varchar(24) NOT NULL DEFAULT 'escuro' CHECK(theme IN ('escuro','claro','acolhedor')),notice varchar(500) NOT NULL DEFAULT '',messages jsonb NOT NULL DEFAULT '[]'::jsonb CHECK(jsonb_typeof(messages)='array'),active boolean NOT NULL DEFAULT true,FOREIGN KEY(unit_id,client_id) REFERENCES flow_client_units(id,client_id),UNIQUE(id,unit_id));
CREATE TABLE IF NOT EXISTS flow_signage_services (signage_id bigint NOT NULL,unit_id bigint NOT NULL,service_id bigint NOT NULL,PRIMARY KEY(signage_id,service_id),FOREIGN KEY(signage_id,unit_id) REFERENCES flow_signage_profiles(id,unit_id),FOREIGN KEY(service_id,unit_id) REFERENCES flow_client_services(id,unit_id));
